mapper.select:
select
    ia.id,
    ia.applicant_email,
    ia.apply_reason,
    ia.status,
    ia.invite_code,
    ia.reviewer_id,
    ia.review_comment,
    ia.created_at,
    ia.updated_at,
    admin.name as reviewerName
from invite_application ia
left join admin
    on ia.reviewer_id = admin.id

     and ia.id= #{id}
     and ia.applicant_email = #{applicantEmail}
     and ia.apply_reason = #{applyReason}
     and ia.status = #{status}
     and ia.invite_code = #{inviteCode}
     and ia.reviewer_id = #{reviewerId}
     and ia.review_comment = #{reviewComment}
     and ia.created_at = #{createdAt}
     and ia.updated_at = #{updatedAt}
